#!/usr/bin/env python3
"""Embed the committed 512px PNG; rendering is a separate design-time step."""
from pathlib import Path
import struct

root = Path(__file__).resolve().parent.parent
raw = (root / "assets/branding/icon0.png").read_bytes()
if (
    raw[:8] != b"\x89PNG\r\n\x1a\n"
    or len(raw) < 33
    or struct.unpack(">II", raw[16:24]) != (512, 512)
):
    raise SystemExit("launcher icon must be a 512x512 PNG")
out = root / "build/launcher_icon.inc"
out.parent.mkdir(parents=True, exist_ok=True)
with out.open("w") as f:
    f.write(
        "/* Generated by tools/embed_icon.py. */\nstatic const unsigned char uc_launcher_icon[] = {\n"
    )
    for i in range(0, len(raw), 24):
        f.write(",".join(str(b) for b in raw[i : i + 24]) + ",\n")
    f.write("};\n")
